    /**
     * Method to retrieve the Lead via an LeadPrimaryKey.
     * @param 	id Long
     * @return 	Lead
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Lead handle( FindLeadQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getLeadId() );
    }
    
    /**
     * Method to retrieve a collection of all Leads
     *
     * @param	query	FindAllLeadQuery 
     * @return 	List<Lead> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Lead> handle( FindAllLeadQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindLead,
 * but only if the id matches
 *
 * @param		entity	Lead
 */
	protected void emitFindLead( Lead entity ) {
		LOGGER.info("handling emitFindLead" );
		
	    queryUpdateEmitter.emit(FindLeadQuery.class,
	                            query -> query.getFilter().getLeadId().equals(entity.getLeadId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllLead
	 * 
	 * @param		entity	Lead
	 */
	protected void emitFindAllLead( Lead entity ) {
		LOGGER.info("handling emitFindAllLead" );
		
	    queryUpdateEmitter.emit(FindAllLeadQuery.class,
	                            query -> true,
	                            entity);
	}

